// 1. 获取当前文档全部封装源码
const sources = await eda.sys_FileManager.getDocumentFootprintSources();

// 2. 输出封装数量与每个封装的源码长度
console.log('封装数量：', sources.length);
sources.forEach((item, i) => {
  console.log('[' + i + '] footprintUuid：', item.footprintUuid, '源码长度：', item.documentSource.length);
});
